function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const runId = uuidv4();

return $input.all().map(item => ({
  json: {
    ...item.json,
    run_id: runId
  }
}));

// ============================================================
// CODE - AVALIAR BENCHMARK DUCKLAKE v2.2.31
// Modo: Run Once for Each Item
//
// Objetivo:
// Avaliar a resposta SQL do agente contra a tabela
// public.ai_ducklake_benchmarks.
//
// Regras principais desta versão:
// - Sem LIMIT SQL por padrão.
// - LIMIT só é aceito quando a pergunta pede número explícito
//   como "top 5", "10 maiores", "5 menores" etc.
// - "maiores", "menores", "principal", "melhor" e "pior"
//   sem número explícito exigem ranking/ORDER BY, mas não LIMIT.
// - Grava SEMPRE a agent_version do benchmark, não a versão interna
//   retornada pelo agente.
// - Aceita dev_lakehouse.main_gold, prod_lakehouse.main_gold,
//   {{ducklake_alias}}.main_gold e main_gold como aliases operacionais.
// - Mantém compatibilidade com o modelo 4 simplificado, sem exigir
//   tabelas de rateio quando a pergunta não pedir consolidação/rateio.
// ============================================================

const resposta = $json || {};

let benchmark = {};
try {
  benchmark = $('Loop Over Items').first().json || {};
} catch (e) {
  benchmark = {};
}

const BENCHMARK_AGENT_VERSION =
  benchmark.agent_version ||
  'v2.2.31-benchmark-historico-cliente';

// ============================================================
// Helpers
// ============================================================

function toArray(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      return [];
    }
  }

  return [];
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function safeJson(value) {
  if (value === undefined) return null;
  return value;
}

function hasAny(text, terms) {
  return terms.some(term => text.includes(normalizeText(term)));
}

function perguntaPedeLimiteExplicito(perguntaRaw) {
  const p = normalizeText(perguntaRaw);

  return (
    /\btop\s*\d+\b/.test(p) ||
    /\b(primeiros|primeiras|ultimos|ultimas)\s+\d+\b/.test(p) ||
    /\b\d+\s+(maiores|menores|principais|melhores|piores|primeiros|primeiras|ultimos|ultimas)\b/.test(p) ||
    /\b(traga|liste|mostrar|mostre|retorne)\s+\d+\b/.test(p)
  );
}

function sqlContemLimit(sqlRaw) {
  return /\blimit\s+\d+\b/i.test(String(sqlRaw || ''));
}

function perguntaPedeRateiosOuConsolidado(perguntaNorm) {
  return hasAny(perguntaNorm, [
    'rateio',
    'rateios',
    'consolidado',
    'consolidada',
    'consolidado com rateios',
    'incluindo rateios',
    'com rateios',
    'visao total',
    'visão total',
    'total com rateios'
  ]);
}

function sqlPareceModelo4Simplificado(sqlNorm) {
  if (!sqlNorm) return false;

  const temCentroCusto =
    sqlNorm.includes('centro_custo') ||
    sqlNorm.includes('nome_centro_custo');

  const temOpexRealizado =
    sqlNorm.includes('opex_realizado') ||
    sqlNorm.includes('opex_realizado_rs') ||
    sqlNorm.includes('valor_realizado');

  const temOpexOrcado =
    sqlNorm.includes('opex_orcado') ||
    sqlNorm.includes('opex_orcado_rs') ||
    sqlNorm.includes('valor_orcado');

  const temVariancia =
    sqlNorm.includes('variancia') ||
    sqlNorm.includes('variancia_rs');

  const temOrcamento =
    sqlNorm.includes('gold_orcamento');

  const temOpex =
    sqlNorm.includes("like '09 -%'") &&
    sqlNorm.includes("like '10 -%'") &&
    sqlNorm.includes("like '12 -%'");

  return (
    temCentroCusto &&
    temOpexRealizado &&
    temOpexOrcado &&
    temVariancia &&
    temOrcamento &&
    temOpex
  );
}

function perguntaPareceModelo4Simplificado(perguntaNorm, intentEsperada, intentDetectada, sqlNorm) {
  const falaCentroCusto = hasAny(perguntaNorm, [
    'centro de custo',
    'centros de custo',
    'setor',
    'setores',
    'area',
    'departamento',
    'cc'
  ]);

  const falaOrcamentoOuOpex = hasAny(perguntaNorm, [
    'orcamento',
    'orçamento',
    'orcado',
    'orçado',
    'budget',
    'economia',
    'abaixo do orcamento',
    'acima do orcamento',
    'consumiram menos',
    'consumo',
    'consumido',
    'opex',
    'desempenho',
    'melhor desempenho',
    'pior desempenho'
  ]);

  const intentModelo4 =
    intentEsperada === 'opex_por_centro_custo' ||
    intentDetectada === 'opex_por_centro_custo';

  return (
    (intentModelo4 || (falaCentroCusto && falaOrcamentoOuOpex) || sqlPareceModelo4Simplificado(sqlNorm)) &&
    !perguntaPedeRateiosOuConsolidado(perguntaNorm)
  );
}

function containsPercentualAlias(sqlNorm) {
  return (
    sqlNorm.includes('percentual') ||
    sqlNorm.includes('perc_') ||
    sqlNorm.includes('_perc') ||
    sqlNorm.includes('resultado_perc_rol') ||
    sqlNorm.includes('perc_representatividade') ||
    sqlNorm.includes('perc_orcado_consumido') ||
    sqlNorm.includes('cmv_perc_rol') ||
    sqlNorm.includes('lucro_bruto_perc_rol') ||
    sqlNorm.includes('opex_perc_rol') ||
    sqlNorm.includes('margem_contribuicao_perc_rol') ||
    sqlNorm.includes('resultado_liquido_perc_rol') ||
    sqlNorm.includes('resultado_percentual_rol') ||
    sqlNorm.includes('representatividade') ||
    sqlNorm.includes('/ nullif') ||
    sqlNorm.includes('/nullif') ||
    sqlNorm.includes(' / ')
  );
}

function containsPercentualConsumidoAlias(sqlNorm) {
  return (
    sqlNorm.includes('percentual_consumido') ||
    sqlNorm.includes('perc_orcado_consumido') ||
    sqlNorm.includes('consumo') ||
    sqlNorm.includes('consumido') ||
    sqlNorm.includes('/ nullif') ||
    sqlNorm.includes('/nullif') ||
    sqlNorm.includes(' / ')
  );
}

function containsLakehouseAlias(sqlNorm) {
  return (
    sqlNorm.includes('dev_lakehouse.main_gold') ||
    sqlNorm.includes('prod_lakehouse.main_gold') ||
    sqlNorm.includes('{{ducklake_alias}}.main_gold') ||
    sqlNorm.includes('main_gold')
  );
}

function containsTerm(sqlNorm, term) {
  const termo = normalizeText(term);
  if (!termo) return true;

  if (
    termo === 'percentual' ||
    termo === 'percentuais' ||
    termo === 'percentual sobre rol' ||
    termo === '% sobre rol'
  ) {
    return containsPercentualAlias(sqlNorm);
  }

  if (
    termo === 'percentual_consumido' ||
    termo === 'percentual consumido' ||
    termo === 'percentual de orcamento consumido' ||
    termo === 'percentual de orçamento consumido'
  ) {
    return containsPercentualConsumidoAlias(sqlNorm);
  }

  if (termo === 'exclusao de unidades corporativas 97, 98 e 99') {
    return (
      sqlNorm.includes("not in ('97', '98', '99')") ||
      sqlNorm.includes("not in('97','98','99')") ||
      sqlNorm.includes("'97', '98', '99'") ||
      sqlNorm.includes("'97','98','99'")
    );
  }

  if (termo === "nk_base = 'imd'") {
    return (
      sqlNorm.includes("nk_base = 'imd'") ||
      sqlNorm.includes('nk_base = "imd"')
    );
  }

  if (termo === "pc.tipo_plano = 'dre'") {
    return (
      sqlNorm.includes("tipo_plano = 'dre'") ||
      sqlNorm.includes('tipo_plano = "dre"')
    );
  }

  if (termo === "cc.tipo_centro_custo = 'gerencial'") {
    return (
      sqlNorm.includes("tipo_centro_custo = 'gerencial'") ||
      sqlNorm.includes('tipo_centro_custo = "gerencial"')
    );
  }

  if (termo.includes('opex pelos grupos dre 09')) {
    return (
      sqlNorm.includes("like '09 -%'") &&
      sqlNorm.includes("like '10 -%'") &&
      sqlNorm.includes("like '12 -%'")
    );
  }

  if (termo.includes('rol pelos grupos dre 01')) {
    return (
      sqlNorm.includes("like '01 -%'") &&
      sqlNorm.includes("like '02 -%'") &&
      sqlNorm.includes("like '03 -%'")
    );
  }

  if (
    termo === 'dev_lakehouse.main_gold' ||
    termo === '{{ducklake_alias}}.main_gold' ||
    termo === 'ducklake_alias' ||
    termo === 'main_gold'
  ) {
    return containsLakehouseAlias(sqlNorm);
  }

  if (termo === 'order by') {
    return sqlNorm.includes('order by');
  }

  if (termo === 'limit') {
    return sqlContemLimit(sqlNorm);
  }

  return sqlNorm.includes(termo);
}

function shouldIgnoreRequiredTable(tabelaNorm, perguntaNorm, intentEsperada, intentDetectada, sqlNorm) {
  const modelo4Simplificado = perguntaPareceModelo4Simplificado(
    perguntaNorm,
    intentEsperada,
    intentDetectada,
    sqlNorm
  );

  if (!modelo4Simplificado) return false;

  return (
    tabelaNorm === 'gold_rateios_lancamentos_contabeis' ||
    tabelaNorm === 'gold_rateios_orcamentos'
  );
}

function shouldIgnoreRequiredSqlTerm(termoNorm, perguntaNorm, intentEsperada, intentDetectada, sqlNorm) {
  const modelo4Simplificado = perguntaPareceModelo4Simplificado(
    perguntaNorm,
    intentEsperada,
    intentDetectada,
    sqlNorm
  );

  if (!modelo4Simplificado) return false;

  return (
    termoNorm === 'gold_rateios_lancamentos_contabeis' ||
    termoNorm === 'gold_rateios_orcamentos'
  );
}

// ============================================================
// Campos do benchmark
// ============================================================

const benchmarkId = benchmark.id || benchmark.benchmark_id || null;
const pergunta = benchmark.pergunta || resposta.pergunta || '';
const perguntaNorm = normalizeText(pergunta);
const intentEsperada = benchmark.intent_esperada || '';
const categoria = benchmark.categoria || null;

const tabelasObrigatorias = toArray(benchmark.tabelas_obrigatorias);
const filtrosObrigatorios = toArray(benchmark.filtros_obrigatorios);
const deveConterSql = toArray(benchmark.deve_conter_sql);
const naoDeveConterSql = toArray(benchmark.nao_deve_conter_sql);

// ============================================================
// Campos da resposta do agente
// ============================================================

const intentDetectada =
  resposta.intencao ||
  resposta.detected_intent ||
  resposta.intent_detectada ||
  resposta.intent ||
  resposta.intencao_detectada ||
  resposta.entrega_watson?.detected_intent ||
  resposta.entrega_watson?.intent ||
  null;

const sql =
  resposta.sql ||
  resposta.sql_query ||
  resposta.query ||
  resposta.query_executada_watson ||
  resposta.query_para_copiar ||
  resposta.entrega_watson?.query_para_copiar ||
  resposta.entrega_watson?.sql ||
  resposta.entrega_watson?.sql_query ||
  null;

const sqlNorm = normalizeText(sql);

const validationStatus =
  resposta.validacao_offline?.status ||
  resposta.validation_status ||
  resposta.status_validacao ||
  'nao_informado';

const validationErrors =
  resposta.validacao_offline?.errors ||
  resposta.validation_errors ||
  [];

const validationWarnings =
  resposta.validacao_offline?.warnings ||
  resposta.validation_warnings ||
  [];

const tabelasUsadas =
  resposta.tabelas_usadas ||
  resposta.tables_used ||
  [];

const filtrosAplicados =
  resposta.filtros_aplicados ||
  [];

const erros = [];
const avisos = [];

// ============================================================
// 1. Resposta do agente
// ============================================================

if (!resposta || typeof resposta !== 'object') {
  erros.push('Resposta do agente ausente ou inválida.');
}

if (resposta.success === false) {
  erros.push(
    resposta.detalhe ||
    resposta.resposta ||
    resposta.message ||
    resposta.error_message ||
    'Agente retornou success=false.'
  );
}

if (!intentDetectada) {
  erros.push('Resposta do agente não contém intenção detectada.');
} else if (intentEsperada && intentDetectada !== intentEsperada) {
  erros.push(`Intenção incorreta. Esperado: ${intentEsperada}. Detectado: ${intentDetectada}.`);
}

if (!sql || !String(sql).trim()) {
  erros.push('Resposta do agente não contém SQL gerado.');
}

// ============================================================
// 2. Regra global v2.2.31: sem LIMIT SQL padrão
// ============================================================

if (sql) {
  const temLimit = sqlContemLimit(sql);
  const pedeLimitExplicito = perguntaPedeLimiteExplicito(pergunta);

  if (temLimit && !pedeLimitExplicito) {
    erros.push('SQL contém LIMIT sem número explícito solicitado pelo usuário. Regra v2.2.31: sem LIMIT SQL padrão.');
  }

  if (!temLimit && pedeLimitExplicito) {
    avisos.push('Pergunta parece pedir quantidade explícita, mas a SQL não contém LIMIT. Verificar se o ranking sem LIMIT é aceitável para este caso.');
  }
}

// ============================================================
// 3. Validação SQL contra critérios do benchmark
// ============================================================

if (sql) {
  for (const tabela of tabelasObrigatorias) {
    const tabelaNorm = normalizeText(tabela);

    if (shouldIgnoreRequiredTable(tabelaNorm, perguntaNorm, intentEsperada, intentDetectada, sqlNorm)) {
      avisos.push(`Tabela obrigatória ignorada por Modelo 4 simplificado: ${tabela}`);
      continue;
    }

    if (!sqlNorm.includes(tabelaNorm)) {
      erros.push(`SQL não contém tabela obrigatória: ${tabela}`);
    }
  }

  for (const filtro of filtrosObrigatorios) {
    if (!containsTerm(sqlNorm, filtro)) {
      erros.push(`Filtro obrigatório não encontrado: ${filtro}`);
    }
  }

  for (const termo of deveConterSql) {
    const termoNorm = normalizeText(termo);

    if (shouldIgnoreRequiredSqlTerm(termoNorm, perguntaNorm, intentEsperada, intentDetectada, sqlNorm)) {
      avisos.push(`Termo obrigatório ignorado por Modelo 4 simplificado: ${termo}`);
      continue;
    }

    if (!containsTerm(sqlNorm, termo)) {
      erros.push(`SQL não contém termo obrigatório: ${termo}`);
    }
  }

  for (const termo of naoDeveConterSql) {
    const termoNorm = normalizeText(termo);
    if (!termoNorm) continue;

    // LIMIT já é tratado pela regra global v2.2.31.
    // Aqui não duplicamos o erro.
    if (termoNorm === 'limit') {
      continue;
    }

    if (sqlNorm.includes(termoNorm)) {
      erros.push(`SQL contém termo proibido: ${termo}`);
    }
  }
}

// ============================================================
// 4. Validação offline do próprio agente
// ============================================================

if (validationStatus === 'reprovado') {
  erros.push('Validação offline retornou status reprovado.');
}

if (Array.isArray(validationErrors) && validationErrors.length > 0) {
  erros.push(`Validação offline retornou erros: ${JSON.stringify(validationErrors)}`);
}

if (Array.isArray(validationWarnings) && validationWarnings.length > 0) {
  avisos.push(...validationWarnings);
}

// ============================================================
// 5. Limpeza de avisos conhecidos
// ============================================================

const avisosFiltrados = avisos.filter(aviso => {
  const avisoNorm = normalizeText(aviso);

  if (
    perguntaPareceModelo4Simplificado(perguntaNorm, intentEsperada, intentDetectada, sqlNorm) &&
    (
      avisoNorm.includes('tabela obrigatoria ignorada por modelo 4 simplificado') ||
      avisoNorm.includes('termo obrigatorio ignorado por modelo 4 simplificado')
    )
  ) {
    return false;
  }

  return true;
});

// ============================================================
// 6. Resultado final
// ============================================================

const passou = erros.length === 0;

const statusTeste = passou
  ? (avisosFiltrados.length > 0 ? 'aprovado_com_ressalva' : 'aprovado')
  : 'reprovado';

const motivo = passou
  ? (avisosFiltrados.length > 0 ? avisosFiltrados.join(' | ') : 'Benchmark aprovado.')
  : erros.join(' | ');

return {
  json: {
    run_id: benchmark.run_id || null,

    benchmark_id: benchmarkId,
    pergunta,
    categoria,

    intent_esperada: intentEsperada,
    intent_detectada: intentDetectada,

    success: resposta.success === true,
    validation_status: validationStatus,
    validation_errors: safeJson(validationErrors),
    validation_warnings: safeJson(validationWarnings),

    sql_gerado: sql,
    tabelas_usadas: safeJson(tabelasUsadas),
    filtros_aplicados: safeJson(filtrosAplicados),

    passou,
    status_teste: statusTeste,
    motivo,

    // IMPORTANTE:
    // Gravar a versão do benchmark, não a versão interna retornada pelo agente.
    agent_version: BENCHMARK_AGENT_VERSION,

    resposta_completa: safeJson(resposta)
  }
};

// ============================================================
// CODE - MONTAR SQL INSERT BENCHMARK DUCKLAKE
// Modo: Run Once for All Items
// Objetivo: gerar 1 INSERT para cada item avaliado
// ============================================================

function sqlEscape(value) {
  if (value === null || value === undefined) return 'NULL';
  return "'" + String(value).replace(/'/g, "''") + "'";
}

function sqlJson(value) {
  if (value === null || value === undefined) return "'null'::jsonb";
  return sqlEscape(JSON.stringify(value)) + "::jsonb";
}

const items = $input.all();

return items.map(item => {
  const j = item.json;

  const query = `
INSERT INTO public.ai_ducklake_benchmark_runs (
  run_id,
  benchmark_id,
  pergunta,
  categoria,
  intent_esperada,
  intent_detectada,
  success,
  validation_status,
  validation_errors,
  validation_warnings,
  sql_gerado,
  tabelas_usadas,
  filtros_aplicados,
  passou,
  status_teste,
  motivo,
  agent_version,
  resposta_completa
)
VALUES (
  ${sqlEscape(j.run_id)}::uuid,
  ${j.benchmark_id ?? 'NULL'},
  ${sqlEscape(j.pergunta)},
  ${sqlEscape(j.categoria)},
  ${sqlEscape(j.intent_esperada)},
  ${sqlEscape(j.intent_detectada)},
  ${j.success ? 'TRUE' : 'FALSE'},
  ${sqlEscape(j.validation_status)},
  ${sqlJson(j.validation_errors)},
  ${sqlJson(j.validation_warnings)},
  ${sqlEscape(j.sql_gerado)},
  ${sqlJson(j.tabelas_usadas)},
  ${sqlJson(j.filtros_aplicados)},
  ${j.passou ? 'TRUE' : 'FALSE'},
  ${sqlEscape(j.status_teste)},
  ${sqlEscape(j.motivo)},
  ${sqlEscape(j.agent_version)},
  ${sqlJson(j.resposta_completa)}
)
RETURNING id, run_id, benchmark_id, passou, status_teste;
`;

  return {
    json: {
      query
    }
  };
});

// ============================================================
// CODE - PREPARAR RESUMO BENCHMARK DUCKLAKE
// ============================================================

let runId = null;

try {
  runId = $('Code - Gerar Run ID').first().json.run_id;
} catch (e) {
  runId = $input.first()?.json?.run_id || null;
}

if (!runId) {
  throw new Error('run_id não encontrado para gerar resumo.');
}

return [
  {
    json: {
      run_id: runId
    }
  }
];

// ============================================================
// CODE - NORMALIZAR RESPOSTA AGENTE
// v2.2.32-benchmark-response-normalizer-raw-response-safe
// Modo: Run Once for Each Item
//
// Objetivo:
// - Receber resposta do HTTP em texto, JSON ou fullResponse.
// - Parsear body/data/response/text/raw_response quando vierem como string JSON.
// - Extrair SQL de múltiplos caminhos compatíveis.
// - Entregar ao avaliador campos top-level consistentes.
// - Evitar falso negativo quando a resposta veio válida dentro de raw_response.
// - Não usar hardcode de cliente, benchmark, marca ou pergunta.
// ============================================================

const input = $json || {};

// ============================================================
// Helpers
// ============================================================

function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function stringifySafe(value) {
  if (value === null || value === undefined) return null;

  if (typeof value === 'string') return value;

  try {
    return JSON.stringify(value);
  } catch (e) {
    return String(value);
  }
}

function tryParseJson(value) {
  if (value === null || value === undefined) {
    return null;
  }

  if (isObject(value)) {
    return value;
  }

  if (typeof value !== 'string') {
    return null;
  }

  const text = value.trim();

  if (!text) {
    return null;
  }

  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

function firstNonEmpty(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;

    const text = String(value).trim();

    if (text) return value;
  }

  return null;
}

function looksLikeAgentResponse(value) {
  if (!isObject(value)) return false;

  return Boolean(
    value.success !== undefined ||
    value.sql ||
    value.sql_gerado ||
    value.cleaned_sql ||
    value.sql_query ||
    value.query ||
    value.query_para_copiar ||
    value.query_executada_watson ||
    value.entrega_watson ||
    value.validacao_offline ||
    value.intencao ||
    value.intent ||
    value.detected_intent ||
    value.intent_detectada ||
    value.intencao_detectada
  );
}

function parseNestedResponse(value, maxDepth = 5) {
  let current = value;

  for (let depth = 0; depth < maxDepth; depth++) {
    const parsed = tryParseJson(current);

    if (parsed && parsed !== current) {
      current = parsed;
      continue;
    }

    if (!isObject(current)) {
      return current;
    }

    // Caso o HTTP fullResponse tenha encapsulado a resposta real
    // dentro de algum campo textual.
    const nestedCandidates = [
      current.body,
      current.data,
      current.response,
      current.text,
      current.raw_response,
      current.rawResponse,
      current.result,
      current.output
    ];

    let advanced = false;

    for (const candidate of nestedCandidates) {
      if (candidate === null || candidate === undefined) continue;

      const nestedParsed = tryParseJson(candidate);

      if (looksLikeAgentResponse(nestedParsed)) {
        current = {
          ...current,
          ...nestedParsed,
          _normalizer_nested_source: 'nested_json_field'
        };
        advanced = true;
        break;
      }
    }

    if (!advanced) {
      return current;
    }
  }

  return current;
}

function extractSql(response) {
  if (!isObject(response)) return null;

  return firstNonEmpty(
    response.sql_gerado,
    response.sql,
    response.cleaned_sql,
    response.sql_query,
    response.query,
    response.query_executada_watson,
    response.query_para_copiar,

    response.entrega_watson?.query_para_copiar,
    response.entrega_watson?.sql,
    response.entrega_watson?.sql_query,

    response.entrega?.query_para_copiar,
    response.entrega?.sql,
    response.entrega?.sql_query,

    response.resultado?.sql_gerado,
    response.resultado?.sql,
    response.resultado?.cleaned_sql,
    response.resultado?.sql_query,
    response.resultado?.query_para_copiar,
    response.resultado?.query_executada_watson,
    response.resultado?.entrega_watson?.query_para_copiar,

    response.data?.sql_gerado,
    response.data?.sql,
    response.data?.query_para_copiar,
    response.data?.entrega_watson?.query_para_copiar,

    response.body?.sql_gerado,
    response.body?.sql,
    response.body?.query_para_copiar,
    response.body?.entrega_watson?.query_para_copiar
  );
}

function extractIntent(response) {
  if (!isObject(response)) return null;

  return firstNonEmpty(
    response.intencao,
    response.detected_intent,
    response.intent_detectada,
    response.intent,
    response.intencao_detectada,

    response.entrega_watson?.intencao_detectada,
    response.entrega_watson?.detected_intent,
    response.entrega_watson?.intent,
    response.entrega_watson?.intencao,

    response.resultado?.intencao,
    response.resultado?.detected_intent,
    response.resultado?.intent_detectada,
    response.resultado?.intent,
    response.resultado?.intencao_detectada
  );
}

// ============================================================
// Metadados HTTP
// ============================================================

const statusCode =
  input.statusCode ||
  input.status ||
  input.code ||
  input.http_status_code ||
  null;

const headers =
  input.headers ||
  input.responseHeaders ||
  input.http_headers ||
  null;

// ============================================================
// Seleção do payload bruto
// ============================================================

const rawCandidates = [
  input.body,
  input.data,
  input.response,
  input.text,
  input.raw_response,
  input.rawResponse,
  input.result,
  input.output,
  input
];

let parsed = null;
let rawSelected = null;

for (const candidate of rawCandidates) {
  if (candidate === null || candidate === undefined) continue;

  const candidateParsed = parseNestedResponse(candidate);

  if (looksLikeAgentResponse(candidateParsed)) {
    parsed = candidateParsed;
    rawSelected = candidate;
    break;
  }
}

// Fallback: tenta interpretar o objeto inteiro.
if (!parsed || !isObject(parsed)) {
  const fallbackParsed = parseNestedResponse(input);

  if (looksLikeAgentResponse(fallbackParsed)) {
    parsed = fallbackParsed;
    rawSelected = input;
  }
}

// ============================================================
// Resposta inválida controlada
// ============================================================

if (!parsed || !isObject(parsed)) {
  return {
    json: {
      success: false,
      error_message: 'Resposta do webhook não é JSON válido.',
      detalhe: 'O HTTP Request recebeu resposta em texto ou formato inesperado.',
      http_status_code: statusCode,
      http_headers: headers,
      raw_response: stringifySafe(rawSelected ?? input),
      agent_version: 'v2.2.31-benchmark-historico-cliente',
      normalizer_version: 'v2.2.32-benchmark-response-normalizer-raw-response-safe'
    }
  };
}

// ============================================================
// Normalização de campos principais
// ============================================================

const sqlFinal = extractSql(parsed);
const intentFinal = extractIntent(parsed);

const rawResponse =
  typeof input.raw_response === 'string'
    ? input.raw_response
    : typeof rawSelected === 'string'
      ? rawSelected
      : stringifySafe(rawSelected ?? input);

// Mantém entrega_watson, mas garante query_para_copiar quando SQL existir.
const entregaWatsonNormalizada = isObject(parsed.entrega_watson)
  ? {
      ...parsed.entrega_watson,
      query_para_copiar: parsed.entrega_watson.query_para_copiar || sqlFinal || null
    }
  : sqlFinal
    ? {
        query_para_copiar: sqlFinal
      }
    : parsed.entrega_watson;

// ============================================================
// Saída normalizada para o avaliador
// ============================================================

return {
  json: {
    ...parsed,

    // Compatibilidade para o Code - Avaliar Benchmark DuckLake
    sql: sqlFinal || parsed.sql || null,
    sql_gerado: sqlFinal || parsed.sql_gerado || null,
    query_para_copiar: parsed.query_para_copiar || sqlFinal || null,
    query_executada_watson: parsed.query_executada_watson || sqlFinal || null,

    intencao:
      parsed.intencao ||
      intentFinal ||
      null,

    intent_detectada:
      parsed.intent_detectada ||
      parsed.detected_intent ||
      parsed.intent ||
      parsed.intencao_detectada ||
      intentFinal ||
      null,

    entrega_watson: entregaWatsonNormalizada,

    http_status_code: statusCode,
    http_headers: headers,
    raw_response: rawResponse,

    normalizer_version: 'v2.2.32-benchmark-response-normalizer-raw-response-safe',
    normalizer_sql_found: Boolean(sqlFinal),
    normalizer_intent_found: Boolean(intentFinal),
    normalizer_source: 'http_response_normalized'
  }
};
